declarations.code:
template <class T, class U, class... CArgs>

explicit move_only_function(std::in_place_type_t<T>,

    std::initializer_list<U> il, CArgs &&...args);

examples.code:
#include <functional>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::move_only_function<int()> function = [] { return 7; };
    std::move_only_function<int()> other = [] { return 9; };
    function.swap(other);
    assert(function() == 9);
    other = std::move(function);
    assert(other() == 9);
}
